mapper.select:
SELECT c.id, c.ticket_code, c.user_id, c.ticket_id, c.park_id, c.qr_img, c.ticket_name, c.ticket_type, c.price, c.visit_date, c.time_slot, c.holder_name, c.holder_phone, c.holder_id_card, c.status, c.used_time, c.refund_time, c.remark, c.create_by, c.update_by, c.create_time, c.update_time, u.nickname AS userName, u.mobile AS mobile, p.park_name AS parkName FROM shop_trendy_park_user_ticket c LEFT JOIN sys_user u ON u.id = c.user_id LEFT JOIN shop_trendy_park p ON p.id = c.park_id AND p.is_deleted = 0
c.is_deleted = 0
AND c.user_id = #{q.userId}
AND c.park_id = #{q.parkId}
AND c.ticket_id = #{q.ticketId}
AND c.ticket_type = #{q.ticketType}
AND c.status = #{q.status}
AND c.visit_date >= #{q.beginVisitDate}
AND c.visit_date <= #{q.endVisitDate}
AND (c.ticket_code LIKE CONCAT('%', #{q.keyword}, '%') OR c.ticket_name LIKE CONCAT('%', #{q.keyword}, '%') OR c.holder_name LIKE CONCAT('%', #{q.keyword}, '%') OR c.holder_phone LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY c.id DESC

