UPDATE shop_trendy_park_user_ticket
SET status = 1,
    used_time = #{usedTime}
WHERE id = #{id}
  AND is_deleted = 0
  AND status = 0

UPDATE shop_trendy_park_user_ticket
SET status = 3,
    refund_time = #{refundTime}
WHERE id = #{id}
  AND is_deleted = 0
  AND status IN (0, 1, 2)
